-- Asigna el campo sexo (inferido por primer nombre) a los clientes
-- importados en la migracion historica de CEAPP Santander (Quilichao).
-- El trigger clientes_lock_privileged_columns bloquea editar 'sexo' fuera
-- de una sesion con rol admin (auth.uid()); como este UPDATE se corre
-- directo en el SQL Editor (sin JWT), se desactiva el trigger solo para
-- esta transaccion.
begin;

alter table public.clientes disable trigger clientes_lock_privileged_columns;

